"""A3 handwritten smoke tests; these are not generated by the LLM."""

from subject import calculate_total


def test_normal_purchase():
    assert calculate_total(12, 3) == 36


def test_zero_price_and_quantity():
    assert calculate_total(0, 5) == 0
    assert calculate_total(12, 0) == 0
    assert calculate_total(0, 0) == 0


def test_large_integer_result():
    assert calculate_total(1_000_000, 1_000_000) == 1_000_000_000_000
